    "summary": "Lajos Veres was a stage name. He was born István Lajos Sárközi, 1912–1981, Hungarian Roma, son of a violinist and a singer. He brought a six-man band to Rotterdam in 1935. Fourteen albums. His daughter Mariska took another road.",
    "history": [
      "István Lajos Sárközi was born in a Hungarian village in 1912. The family name is Sárközi (often written Sárközy in the West). His father led a violin orchestra; his mother sang. At nineteen he was already primás of a café band at the Ostende in Budapest. The name he used on the road and on the Dutch sleeves was Lajos Veres.",
      "In 1935 he came to Rotterdam with six men. He returned for good in 1939. The Dutch rooms wanted csárdás and the standing violin. He recorded at least fourteen LPs — Puszta Klänge and the rest of that catalogue. A 1950s Dutch broadcast lists him as first violin with Sárközi Márkus on second violin: the family name still sitting in the second chair.",
      "He married Maria Antonia Ender (1912–1986), born in Germany to French and Russian parents. They raised three daughters in The Hague. The eldest studied piano at the conservatory. Ilonka sang with her father. The youngest, Mariska Veres (1947–2006), left the restaurant book for pop: Shocking Blue, and “Venus.” The archive records her as his child, not as a primás.",
      "Lajos Veres died in 1981 and was cremated in The Hague. Sárközi is also the name of the Budapest violin family still playing classic sets. The Dutch Veres line and the Budapest Sárközi line share a surname common among Hungarian Romani musicians. Without a pedigree this page records both lines."
    ],
