    "origin": "Romanian Roma — Brăila → Scheveningen / Amsterdam / Delft",
    "summary": "Andrei Serban, cimbalom. His son Gregor (1909–1997), violin, the Dutch Stehgeiger. Brother Colea on piano. Sons Gregor junior (piano) and Andrei Şerbănescu (violin). Kurhaus in summer, Hotel de l’Europe in winter.",
    "history": [
      "Gregor Serban was born in Brăila, Romania, on 1 August 1909 (the passport later said the 4th — a feast after the birth). His father Andrei was a cimbalom player. At four Gregor had a small violin; at seven he was in the father’s orchestra. In 1916 the band played in Russia, including for Tsar Nicholas II. An uncle, Codolban, taught him in Paris: conservatory by day, orchestra at night. Berlin conservatory followed. The early repertoire was wide — overtures, operetta, Viennese, Sarasate — not only “gypsy.”",
      "On 1 May 1931 they began in the Netherlands: the Prinsessepaviljoen beside the Kurhaus at Scheveningen. Summer: Kurhaus. Winter: Hotel de l’Europe, Amsterdam. Andrei died in 1935 of a brain haemorrhage while playing at the l’Europe. Gregor left the Hague conservatory to keep the family — mother, sisters, brother Colea.",
      "Colea Serban (b. 1924), pianist, studied in The Hague and sat in the band as a cimbalom-on-piano. A 1958 accident cut his career short; he died young. Gregor went on into old age. In the war they played Amsterdam rooms (Carlton, Tuschinski), then went under. The resistance changed the name to Şerbănescu. Gregor junior put Serban back on the stand in 2002. The other son, Andrei Şerbănescu, violin, kept the wartime name.",
      "After the war: Old Dutch in Rotterdam, Royal in Arnhem, AVRO and KRO radio, the Promenade Orchestra. The last thirty-three years, Gregor junior at the piano beside his father. Gregor died in Delft on 12 December 1997. The family orchestra still carries the name."
    ],
