    "summary": "Ramón Montoya made the flamenco guitar a solo voice. Gitano cattle-trading family in Madrid. Uncle of Carlos Montoya.",
    "history": [
      "Ramón Montoya (2 November 1879 – 20 July 1949, Madrid) was born into a Gitano family of cattle traders and bought his first guitar from that work. He played the cafés de cante before twenty.",
      "From 1912 he partnered Antonio Chacón for more than a decade. Both sat the Concurso de Cante Jondo in Granada, 1922. In traditional flamenco the guitar sat behind cante and baile. Montoya’s playing often overpowered the singer. He then took the logical step: solo concert guitar. Later solo careers — Sabicas, Paco de Lucía — stand on that chair.",
      "Carlos Montoya (1903–1993), his nephew, took that solo guitar abroad. This is a Calé toque family. Restaurant violin and gypsy jazz are other traditions."
    ],
