    "about": [
      "For centuries in the southern Balkans, Roma held the zurla (zurna) and tapan (davul) pairing almost exclusively — outdoor ritual music of double-reed and drum. Brass later took the same social job: weddings, saints’ days, processions.",
      "Čoček (kyuchek in Bulgaria) is both a solo dance and a musical genre, often in 9/8 or 7/8, ornamented and improvisatory. Bulgarian wedding clarinet — Ivo Papazov and the Kardzhali school — absorbed jazz phrasing without leaving the dance floor.",
      "Tallava grew among Kosovo Roma in the 1990s and spread through Albania. Šaban Bajramović in Niš and Esma Redžepova in Skopje made Romani song a popular voice of Yugoslavia. Chalga in Bulgaria is the electric popular descendant. None of this is gypsy jazz. It is a different rhythm, a different instrument, a different job.",
      "Carol Silverman documented a split: festival brass as “Gypsy” spectacle; synthesizer wedding bands as what many Roma actually dance to. Brass is real. It is not the whole job.",
      "Library films now sit on this page: Library of Congress Homegrown, 2019 — Eva Salina and Peter Stan, Serbian Roma song. RFE/RL, 2012 — Khamoro in Prague. Ibro Lolov’s Sofia dance, ARC 2014. Selime Bajrami (Kosovo, Jugoton 1969) and a Greek compilation are listed under Later. No new family from a playlist."
    ],
