    "summary": "Choirs, seven-string guitar, and the urban romance. Russian Romani theatre companies made this sound a national fashion in the nineteenth century. A guitar style with few remaining masters still carries it.",
    "about": [
      "Romani choirs performed in Moscow and St Petersburg restaurants and on the imperial stage. The repertoire mixed Romani-language songs with Russian romances — sentimental, virtuosic, often in a minor that Russian audiences heard as “Gypsy”.",
      "The seven-string guitar (semistrunnaya) was the domestic instrument of this world: a tuning and a right-hand style distinct from the Spanish six-string. Players such as the Kolpakov family still teach a line that almost disappeared when the six-string took over. Oleg Timofeyev documents it with them.",
      "Theatre Romen in Moscow, founded 1931, is the institutional centre — the world’s oldest professional Romani theatre. Anna Piotrowska’s work on tsyganshchina is the scholarly frame: choirs and romances as a staged public music, not a village fossil."
    ],
