    "summary": "In the 1930s Hungarian Roma, Romanian Roma and Sinti violinists took the Central European restaurant repertoire into Dutch hotels and pavilions. The standing primás: csárdás, hora, Russian standards — still touring. Django’s pompe is another right hand.",
    "about": [
      "A quiet migration of violinists changed the sound of Dutch restaurants. Hungarian Roma, Romanian Roma, and Sinti families arrived one after another — not as refugees at first, but as working musicians following the money and the appetite for this music.",
      "Lajos Veres came in 1935 with a six-man band for Rotterdam and never left. The Weiss family of Tata Mirando fled the Nazis in 1936 and found a new home in the same cafés. Gregor Serban had already been there since 1931, playing the Kurhaus with his father’s orchestra. They stayed because the Dutch kept asking for more.",
      "Meanwhile in Budapest the Lakatos and Sárközy families kept the same repertoire alive — Bihari’s line, the restaurant violin tradition that never died. Two Dutch worlds sit side by side: Sinti gypsy jazz, and this older café orchestra. They shared cities. They did not share a right hand.",
      "The café book itself was already mixed. Csárdás and nóta from Hungary, hora from Romania, Russian romances from the choir and seven-string tradition — Dark Eyes, Two Guitars, the rest of that shelf. Hungarian Roma played it as their craft. Romanian Roma brought hora and cimbalom into the same night. Sinti families such as Tata Mirando played it because Dutch hotels asked for “gypsy,” not for a kinship. Same menu. Not the same people. The Roma and Sinti chapter is the map of that difference."
    ],
