    "summary": "An urban Romanian song-dance genre, played largely by Romani musicians (lăutari and manelişti), loved at weddings and clubs, and argued over in public. It is not the village taraf. It grew from that professional world.",
    "about": [
      "Manele (singular manea) mix local traditional and popular music with Balkan and Middle Eastern elements. Beissinger, Rădulescu and Giurchescu (Manele in Romania, 2016) is the book. The genre emerged during late communism outside state-sanctioned channels, then exploded after 1989 under the name muzică orientală — a sound of new money, youth, and a paying elite. Working-class youth (Romanian, Roma, and others) dance to it. Intellectuals have called it vulgar, foreign, immoral. Both the wedding and the argument belong in the archive.",
      "Giurchescu and Rădulescu: manele are a syncretic merging of music, text, dance, gesture and behaviour, created by hired manelişti at parties. Beissinger’s “Village Manele” follows one rural Romani family as they altered their artistry when the urban genre reached the village. Those names wait until the ethnography is recorded here.",
      "Rădulescu’s older argument still holds in the next room: muzică lăutărească is Romanian music kept alive by Romani professionals. Manele is what part of that profession became when the room, the amp and the market changed.",
      "No family pages yet. Living manelişti who want a family page can write here. Clips here come from official or library sources."
    ],
