        "paragraphs": [
          "Verbunkos grew as recruiting-dance music in the eighteenth century and became a national idiom. The csárdás, with its slow lassú and fast friss, is the public dance form. Hallgató — music for listening — is the slow, rubato violin line that a primás stretches over cimbalom and bass.",
          "Franz Liszt’s Hungarian Rhapsodies and Brahms’s dances took this professional Romani style into the concert hall, often under the label “Gypsy.” Liszt went further: he claimed a Gypsy origin for Hungarian music. Bartók and Kodály later reversed that claim. Village peasant song, they said, was the true Hungarian folk; urban café “Gypsy music” was Hungarian popular art music performed by Roma — a different thing, and in their writing often a lesser thing. Bartók described Gypsy performance as destroying the unity of folk song by turning vocal pieces instrumental.",
          "Bálint Sárosi catalogued the restaurant band more carefully than anyone, and still promoted the idea that “Gypsy music” is not, in fact, Romani music — except the Vlax vocal variety he barely mentioned. Petra Gelbart, on RomArchive, calls that a double standard: if an improvisation sounds notably different from the original, that too is composing. Roma took harmonic structure from mainstream practice; the melodic and rhythmic development of the café style has been shaped by Romani traditions for generations. This archive files the primás as a maker, not a copyist. The full argument is on the Scholars page.",
          "The players themselves were already playing nóta, opera tunes, waltzes and whatever the paying table asked. A living band is a library, not a museum label. IMSLP holds the public-domain Liszt rhapsodies and Brahms dances — reception history, not field tradition."
        ]
