          "The Sárközi family sits in the same city: Lajos Sárközi Sr. and Jr., Rudolf Sárközi on bass, József Sárközi of the Rajkó Orchestra. Lajos Jr. still plays the Százéves Étterem. The Dutch primás Lajos Veres was born István Lajos Sárközi. Full registers are under Families.",
          "The 100 Member Hungarian Gypsy Orchestra — 100 Tagú Cigányzenekar — was founded in 1985 as a tribute to the primás Sándor Járóka Sr. It debuted at the Budapest Spring Festival in 1986, was listed among the Hungarikums in 2014, and still plays the restaurant book as a symphony: Liszt and Brahms beside csárdás and nóta. A living public face of the same profession, not a village band.",
          "Named chairs of the restaurant book, besides the Lakatos and Sárközi families: Járóka, Boross, Toki Horváth, Sánta, Danyi, Lendvai Csócsi, Veres, 100 Tagú Cigányzenekar. Magyari Imre is still on Later (birth day disagrees). Rinaldo Oláh is a Slovak primás of the same professional world.",
          "Czinka Panna (1711–1772) stands at the far end of the same professional story: a named Romani woman bandleader in the eighteenth-century Kingdom of Hungary, proof that the orchestra was already a Romani occupation before the word “csárdás” was a tourist poster. In the 1930s that same sound crossed the North Sea. The Dutch chapter is next door.",
          "Musical training is not one road. Tess Lulu Orban (RomArchive, Hungary) notes that many amateur Romungro and Lovari musicians play by ear and are looked down on for it, while a good number of professional Romani vocalists and instrumentalists have attended major institutions, including the Liszt Academy in Budapest. Both things are true. Fekete Vonat is a 1990s Romani hip-hop name — present-day Central Europe, not this café book."
