          "Theatre Romen, Moscow, founded 1931, is the world’s oldest professional Romani theatre and the institutional centre of this public music. Its archive and foyer hold protocols, play texts, posters, photographs and costumes. Further records sit in RGALI. A living institution, not only a vault."
