        "id": "unheard",
        "kicker": "04",
        "title": "What this archive cannot hear",
        "paragraphs": [
          "The unrecorded is not a romantic gap. It is the default. Contact exists so living families can file a memory, a date, a photograph. Nothing is published until it is recorded under a family. Later, permission to add will widen. Firsthand accounts from musicians Daniel plays with belong here when they are given — not scraped."
        ]
